import sqlite3, json

conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row

flights = {}
for r in conn.execute(\"SELECT * FROM flights WHERE source_skill='tau2Airline'\"):
    dates_json = json.loads(r['dates_json'] or '{}')
    flights[r['flight_id']] = {
        'flight_number': r['flight_id'],
        'origin': r['origin'],
        'destination': r['destination'],
        'departure_time': r['departure_time'],
        'arrival_time': r['arrival_time'],
        'dates': dates_json,
    }

# All LAX departures (non-direct-to-SFO) with available dates
print('=== All available LAX departures (excluding direct LAX->SFO) ===')
lax_non_sfo = []
for f in flights.values():
    if f['origin'] == 'LAX' and f['destination'] != 'SFO':
        avail = sorted([d for d, info in f['dates'].items() if info.get('status') == 'available'])
        if avail:
            lax_non_sfo.append(f)
            print(f\"  {f['flight_number']}: LAX -> {f['destination']} | dates: {avail} | dep={f['departure_time']} arr={f['arrival_time']}\")

if not lax_non_sfo:
    print('  (none - all LAX flights go directly to SFO)')

# Also show all LAX destinations
print('\\n=== All LAX destinations ===')
lax_dests = set()
for f in flights.values():
    if f['origin'] == 'LAX':
        lax_dests.add(f['destination'])
print(f'Destinations from LAX: {lax_dests}')

# Show origins that connect to SFO
print('\\n=== Origins with flights to SFO ===')
sfo_origins = set()
for f in flights.values():
    if f['destination'] == 'SFO':
        sfo_origins.add(f['origin'])
print(f'Origins to SFO: {sfo_origins}')

print(f'\\nOverlap (LAX dests that also fly to SFO): {lax_dests & sfo_origins - {\"SFO\"}}')

# Also: check ALL available dates for direct LAX->SFO  
print('\\n=== Direct LAX -> SFO available dates ===')
for f in flights.values():
    if f['origin'] == 'LAX' and f['destination'] == 'SFO':
        avail = sorted([d for d, info in f['dates'].items() if info.get('status') == 'available'])
        if avail:
            print(f\"  {f['flight_number']}: dates={avail} dep={f['departure_time']} arr={f['arrival_time']}\")

conn.close()
